	"dataSources": {
		"ds_11rs4gK3_ds_actf5Njv": {
			"name": "Sankey - Report costs by service category",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" BilledCost > 0\n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, BillingCurrency, BillingPeriodStart, ServiceCategory \n| stats sum(TotalBilledCost) AS TotalBilledCost BY ProviderName,ServiceCategory\n| sort ServiceCategory -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_3TAz6p6F": {
			"name": "Column - Report spending across billing periods for a provider by service category",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| stats sum(sumBilledCost) AS TotalBilledCost BY ServiceCategory\n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_3nBpYmlL": {
			"name": "Table - Report commitment discount purchases",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" ChargeCategory = \"Purchase\" CommitmentDiscountId = * \n| stats min(ChargePeriodStart) AS ChargePeriodStart,\n    max(ChargePeriodEnd) AS ChargePeriodEnd,\n    sum(sumBilledCost) AS TotalBilledCost BY ProviderName, BillingAccountId, CommitmentDiscountId, CommitmentDiscountType, ChargeFrequency \n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_6QHySW5E": {
			"name": "SingleValue - Report costs by provider name",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName"
			},
			"type": "ds.chain"
		},
		"ds_6kHYydLU_ds_hxgrpzzV_ds_TXRT4ueI": {
			"name": "SingleValue - Total Billed Cost",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| stats sum(sumBilledCost) AS TotalBilledCost "
			},
			"type": "ds.chain"
		},
		"ds_6sORNjwK": {
			"name": "MultiSelect - Tagged with",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search EffectiveCost != 0 \n| rex field=Tags max_match=0 \"(['\\\"])(?<tag_keys>[^'\\\"]+)\\1:\\s*\\1(?<tag_values>[^'\\\"]+)\\1\"\n| table tag_values \n| mvexpand tag_values \n| dedup tag_values \n| sort tag_values \n| table tag_values"
			},
			"type": "ds.chain"
		},
		"ds_7YfvYKSQ": {
			"name": "Donat - Report application cost month over month",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| rex field=Tags max_match=0 \"(['\\\"])$tag$\\1:\\s*\\1(?<Tagged>[^'\\\"]+)\\1\"\n| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" EffectiveCost > 0 Tagged  IN ($taggedwith|s$)\n| stats sum(sumEffectiveCost) as TotalEffectiveCost by Tagged \n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_AibkCDE3": {
			"name": "Dropdown - Service Name",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\"\n| dedup ServiceName \n| table ServiceName"
			},
			"type": "ds.chain"
		},
		"ds_CUVED3JK": {
			"name": "Table - Report costs by service category and subcategory",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| eval ServiceSubcategory = if(isnull(ServiceSubcategory), \"n/a\", ServiceSubcategory)\n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, BillingCurrency, BillingPeriodStart, ServiceCategory, ServiceSubcategory \n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_Ke00VwAW": {
			"name": "Column - Report costs by service category and subcategory",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| eval ServiceSubcategory = if(isnull(ServiceSubcategory), \"n/a\", ServiceSubcategory)\n| stats sum(sumBilledCost) AS TotalBilledCost BY ServiceCategory"
			},
			"type": "ds.chain"
		},
		"ds_MM5DaCs5": {
			"name": "Dropdown - Service Category",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" \n| dedup ServiceCategory \n| table ServiceCategory"
			},
			"type": "ds.chain"
		},
		"ds_MfGWXtn3": {
			"name": "SingleValue - Report recurring charges for commitment-based discounts over a period",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" ChargeFrequency = \"Recurring\" CommitmentDiscountId=\"*\"\n| stats sum(sumBilledCost) AS TotalBilledCost BY ProviderName"
			},
			"type": "ds.chain"
		},
		"ds_NBdWvL9x": {
			"name": "SingleValue - Report costs by service category",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ServiceCategory\n    | sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_QMiEsDfq": {
			"name": "Column - Report application cost month over month",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| rex field=Tags max_match=0 \"(['\\\"])$tag$\\1:\\s*\\1(?<Tagged>[^'\\\"]+)\\1\"\n| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" EffectiveCost > 0 Tagged  IN ($taggedwith|s$)\n| timechart span=1mon eval(round(sum(sumEffectiveCost),2)) as TotalEffectiveCost by Tagged \n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_QopnVBRS": {
			"name": "Table - Report refunds by subaccount within a billing period",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" SubAccountName IN ($SubAccountNameMulti|s$)\n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, ServiceCategory, SubAccountName\n| sort -TotalBilledCost\n| search TotalBilledCost != 0"
			},
			"type": "ds.chain"
		},
		"ds_SKznnxba": {
			"name": "Table - Report spending across billing periods for a provider by service category",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, BillingAccountName, BillingAccountId, BillingCurrency, BillingPeriodStart, ServiceCategory\n| sort ProviderName ServiceCategory -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_TXRT4ueI": {
			"name": "SingleValue - Total Billed Cost by Sub Account Name",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" SubAccountName IN ($SubAccountNameMulti|s$)\n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName"
			},
			"type": "ds.chain"
		},
		"ds_U183Ys62": {
			"name": "BASE Search",
			"options": {
				"query": "| `focus_base_search`"
