		"ds_UrW3jpod": {
			"name": "Dropdown - Tag",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search EffectiveCost != 0 \n| rex field=Tags max_match=0 \"(['\\\"])(?<tag_keys>[^'\\\"]+)\\1:\\s*\\1(?<tag_values>[^'\\\"]+)\\1\"\n| table tag_keys \n| mvexpand tag_keys \n| replace \" org\" with \"org\" in tag_keys \n| dedup tag_keys \n| table tag_keys"
			},
