			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| stats sum(BilledCost) AS TotalBilledCost \n    BY SubAccountName \n| sort -TotalBilledCost SubAccountName \n| table SubAccountName"
			},
			"type": "ds.chain"
		},
		"ds_actf5Njv": {
			"name": "Table - Report costs by service category",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY BillingCurrency, ServiceCategory \n| sort -TotalBilledCost\n| addcoltotals labelfield=TotalCost"
