				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" ChargeFrequency = \"Recurring\" CommitmentDiscountId=\"*\" \n| stats sum(sumBilledCost) AS TotalBilledCost BY BillingPeriodStart, CommitmentDiscountId, CommitmentDiscountCategory, CommitmentDiscountType, ChargeFrequency"
			},
			"type": "ds.chain"
		},
		"ds_hnlQ3GgG": {
			"name": "Table - Report service costs by providers subaccount",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" SubAccountName IN ($SubAccountNameMulti|s$) SubAccountId = *\n| stats sum(sumEffectiveCost) AS TotalEffectiveCost \n    BY ProviderName, ServiceCategory, SubAccountName\n| sort -TotalEffectiveCost"
