		"ds_iW3SINAS": {
			"name": "Table - Report application cost month over month",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| rex field=Tags max_match=0 \"(['\\\"])$tag$\\1:\\s*\\1(?<Tagged>[^'\\\"]+)\\1\"\n| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" EffectiveCost > 0 Tagged  IN ($taggedwith|s$)\n| eval Month = BillingPeriodStart \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY Month Tagged \n| eval TotalEffectiveCost = round(TotalEffectiveCost,2) \n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
