			"type": "ds.chain"
		},
		"ds_wOHrmlrb_ds_QopnVBRS": {
			"name": "Bar - Report refunds by subaccount within a billing period BARCHART",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" SubAccountName IN ($SubAccountNameMulti|s$) BilledCost != 0\n| stats sum(sumBilledCost) AS TotalBilledCost \n    BY ProviderName, ServiceCategory, SubAccountName, SubAccountId, BillingAccountId\n| chart eval(round(sum(TotalBilledCost),2)) AS TotalBilledCost BY SubAccountName, ServiceCategory\n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_zeih9YlA": {
			"name": "SingleValue - Report costs by service category and subcategory",
			"options": {
				"extend": "ds_U183Ys62",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| eval ServiceSubcategory = if(isnull(ServiceSubcategory), \"n/a\", ServiceSubcategory) \n| stats sum(sumBilledCost) AS TotalBilledCost BY ServiceCategory"
			},
			"type": "ds.chain"
		}
	},
